//! Low-level definitions of the FUSE wire protocol.
//!
//! All structs, enums and constants in this module describe the binary
//! representation of FUSE requests and replies as exchanged with a
//! virtio-fs device.
//!
//! response out layout eg @ https://github.com/zargony/fuse-rs/blob/bf6d1cf03f3277e35b580f3c7b9999255d72ecf3/src/ll/request.rs#L44
//! op in/out sizes/layout: https://github.com/hanwen/go-fuse/blob/204b45dba899dfa147235c255908236d5fde2d32/fuse/opcode.go#L439
//! possible responses for command: qemu/tools/virtiofsd/fuse_lowlevel.h

/// The node id of the FUSE root directory.
pub const ROOT_ID: u64 = 1;

/// When set in a `GetattrIn`, the `fh` field is used instead of the node id.
pub const GETATTR_FH: u32 = 1 << 0;

/// Symbolic link file type bit.
pub const S_IFLNK: u32 = 40960;

/// File type bit mask.
pub const S_IFMT: u32 = 61440;

/// The opcodes of all supported FUSE operations.
#[repr(u32)]
#[derive(Copy, Clone, Debug)]
#[allow(dead_code)]
pub enum Opcode {
	Lookup = 1,
	Forget = 2, // no reply
	Getattr = 3,
	Setattr = 4,
	Readlink = 5,
	Symlink = 6,
	Mknod = 8,
	Mkdir = 9,
	Unlink = 10,
	Rmdir = 11,
	Rename = 12,
	Link = 13,
	Open = 14,
	Read = 15,
	Write = 16,
	Statfs = 17,
	Release = 18,
	Fsync = 20,
	Setxattr = 21,
	Getxattr = 22,
	Listxattr = 23,
	Removexattr = 24,
	Flush = 25,
	Init = 26,
	Opendir = 27,
	Readdir = 28,
	Releasedir = 29,
	Fsyncdir = 30,
	Getlk = 31,
	Setlk = 32,
	Setlkw = 33,
	Access = 34,
	Create = 35,
	Interrupt = 36,
	Bmap = 37,
	Destroy = 38,
	Ioctl = 39,
	Poll = 40,
	NotifyReply = 41,
	BatchForget = 42,
	Fallocate = 43,
	Readdirplus = 44,
	Rename2 = 45,
	Lseek = 46,

	Setvolname = 61,
	Getxtimes = 62,
	Exchange = 63,

	CuseInit = 4096,
}

/// The header of every FUSE request.
#[repr(C)]
#[derive(Debug, Default)]
pub struct InHeader {
	pub len: u32,
	pub opcode: u32,
	pub unique: u64,
	pub nodeid: u64,
	pub uid: u32,
	pub gid: u32,
	pub pid: u32,
	pub padding: u32,
}

/// The header of every FUSE reply.
#[repr(C)]
#[derive(Default, Debug)]
pub struct OutHeader {
