const MAX_READ_LEN: usize = 1024 * 64;
const MAX_WRITE_LEN: usize = 1024 * 64;

const U64_SIZE: u32 = ::core::mem::size_of::<u64>() as u32;

pub trait FuseInterface {
	fn send_command<O: Op>(&mut self, cmd: &Cmd<O>, rsp: &mut Rsp<O>);

	fn get_mount_point(&self) -> String;
}

/// Ties a FUSE operation to its request payload, response payload and opcode.
pub trait Op: fmt::Debug {
	/// The payload of the request sent to the device.
	type In: fmt::Debug;
	/// The payload of the reply received from the device.
	type Out: fmt::Debug;
	/// The opcode identifying this operation on the wire.
	const OPCODE: Opcode;
}

macro_rules! impl_op {
	($name:ident, $in:ty, $out:ty, $opcode:ident) => {
		impl Op for $name {
			type In = $in;
			type Out = $out;
			const OPCODE: Opcode = Opcode::$opcode;
		}
	};
}

/// FUSE_INIT. Performed once to initialize the session.
pub(crate) struct Init;
impl_op!(Init, InitIn, InitOut, Init);
impl Init {
	pub(crate) fn build() -> (Box<Cmd<Self>>, Box<Rsp<Self>>) {
		let cmd = build_cmd(
			ROOT_ID,
			InitIn {
				major: 7,
				minor: 31,
				..Default::default()
			},
			&[],
		);
		let rsp = build_rsp::<Self>(0);
		(cmd, rsp)
	}
}

/// FUSE_LOOKUP. Looks up the node id of `name` in the root directory.
pub(crate) struct Lookup;
impl_op!(Lookup, LookupIn, EntryOut, Lookup);
impl Lookup {
	pub(crate) fn build(name: &str) -> (Box<Cmd<Self>>, Box<Rsp<Self>>) {
		let extra = name_with_nul(name);
		let cmd = build_cmd(ROOT_ID, LookupIn::default(), &extra);
		let rsp = build_rsp::<Self>(0);
		(cmd, rsp)
	}
}

