/// FUSE_LSEEK. Seeks to an offset within an open file.
pub(crate) struct Lseek;
impl_op!(Lseek, LseekIn, LseekOut, Lseek);
impl Lseek {
	pub(crate) fn build(
		nid: u64,
		fh: u64,
		offset: isize,
		whence: SeekWhence,
	) -> (Box<Cmd<Self>>, Box<Rsp<Self>>) {
		let cmd = build_cmd(
			nid,
			LseekIn {
				fh,
				offset: offset.try_into().unwrap(),
				whence: num::ToPrimitive::to_u32(&whence).unwrap(),
