/// Allocates a request of the given operation, fills its header, payload and
/// extra buffer and returns it as a `Box`.
fn build_cmd<O: Op>(nodeid: u64, payload: O::In, extra: &[u8]) -> Box<Cmd<O>> {
	let len = core::mem::size_of::<InHeader>() + core::mem::size_of::<O::In>() + extra.len();
	let layout = Layout::from_size_align(
		len,
		core::cmp::max(
			core::mem::align_of::<InHeader>(),
			core::mem::align_of::<O::In>(),
		),
	)
	.unwrap()
	.pad_to_align();
	let cmd = unsafe {
		let data = alloc::alloc::alloc(layout);
		let raw = core::ptr::slice_from_raw_parts_mut(data, extra.len()) as *mut Cmd<O>;
		ptr::addr_of_mut!((*raw).header).write(InHeader {
			len: len.try_into().unwrap(),
			opcode: O::OPCODE as u32,
			unique: 1,
			nodeid,
			..Default::default()
		});
		ptr::addr_of_mut!((*raw).cmd).write(payload);
		if !extra.is_empty() {
			ptr::copy_nonoverlapping(
				extra.as_ptr(),
				ptr::addr_of_mut!((*raw).extra_buffer) as *mut u8,
				extra.len(),
			);
		}

		Box::from_raw(raw)
	};
	assert_eq!(layout, Layout::for_value(&*cmd));
	cmd
}

/// Allocates a reply buffer of the given operation. The header is initialized,
/// the payload is left uninitialized for the device to write into.
fn build_rsp<O: Op>(extra_len: usize) -> Box<Rsp<O>> {
	let len = core::mem::size_of::<OutHeader>() + core::mem::size_of::<O::Out>() + extra_len;
	let layout = Layout::from_size_align(
		len,
		core::cmp::max(
			core::mem::align_of::<OutHeader>(),
			core::mem::align_of::<O::Out>(),
		),
	)
	.unwrap()
	.pad_to_align();
	let rsp = unsafe {
		let data = alloc::alloc::alloc(layout);
		let raw = core::ptr::slice_from_raw_parts_mut(data, extra_len) as *mut Rsp<O>;
		ptr::addr_of_mut!((*raw).header).write(OutHeader {
			len: len.try_into().unwrap(),
			..Default::default()
		});
		ptr::addr_of_mut!((*raw).body).write(MaybeUninit::uninit());

		Box::from_raw(raw)
	};
	assert_eq!(layout, Layout::for_value(&*rsp));
	rsp
}

/// Appends a NUL terminator to a name, as expected for names in request
/// extra buffers.
fn name_with_nul(name: &str) -> Vec<u8> {
	let mut buf = Vec::with_capacity(name.len() + 1);
	buf.extend_from_slice(name.as_bytes());
	buf.push(0);
	buf
}

pub struct Fuse;

impl PosixFileSystem for Fuse {
	fn open(&self, path: &str, perms: FilePerms) -> Result<Box<dyn PosixFile + Send>, FileError> {
		let mut file = FuseFile {
			fuse_nid: None,
			fuse_fh: None,
			offset: 0,
		};
		// 1.FUSE_INIT to create session
		// Already done

		// Differentiate between opening and creating new file, since fuse does not support O_CREAT on open.
		if !perms.creat {
			// 2.FUSE_LOOKUP(FUSE_ROOT_ID, “foo”) -> nodeid
			file.fuse_nid = self.lookup(path);

			if file.fuse_nid.is_none() {
				warn!("Fuse lookup seems to have failed!");
				return Err(FileError::ENOENT);
			}

			// 3.FUSE_OPEN(nodeid, O_RDONLY) -> fh
			let (cmd, mut rsp) = Open::build(file.fuse_nid.unwrap(), perms.raw);
			get_filesystem_driver()
				.ok_or(FileError::ENOSYS)?
				.lock()
				.send_command(cmd.as_ref(), rsp.as_mut());
			file.fuse_fh = Some(unsafe { rsp.body.assume_init().fh });
		} else {
			// Create file (opens implicitly, returns results from both lookup and open calls)
			let (cmd, mut rsp) = Create::build(path, perms.raw, perms.mode);
			get_filesystem_driver()
				.ok_or(FileError::ENOSYS)?
				.lock()
				.send_command(cmd.as_ref(), rsp.as_mut());

			let inner = unsafe { rsp.body.assume_init() };
			file.fuse_nid = Some(inner.entry.nodeid);
			file.fuse_fh = Some(inner.open.fh);
		}

		Ok(Box::new(file))
	}

	fn opendir(&self, path: &str) -> Result<Box<dyn PosixFile + Send>, FileError> {
		debug!("FUSE opendir: {}", path);

		let mut readdir = FuseDir {
			fuse_nid: None,
			fuse_fh: None,
			offset: 0,
			response: None,
			buffer_offset: 0,
		};

		// Lookup nodeid

		readdir.fuse_nid = self.lookup(path);

		if readdir.fuse_nid.is_none() {
			warn!("Fuse lookup seems to have failed!");
			return Err(FileError::ENOENT);
		}

		// Opendir
		// Flag 0x10000 for O_DIRECTORY might not be necessary
		let (cmd, mut rsp) = Opendir::build(readdir.fuse_nid.unwrap(), 0x10000);
		get_filesystem_driver()
			.ok_or(FileError::ENOSYS)?
			.lock()
			.send_command(cmd.as_ref(), rsp.as_mut());
		readdir.fuse_fh = Some(unsafe { rsp.body.assume_init().fh });

		Ok(Box::new(readdir))
	}

	fn unlink(&self, path: &str) -> core::result::Result<(), FileError> {
		let (cmd, mut rsp) = Unlink::build(path);
		get_filesystem_driver()
			.ok_or(FileError::ENOSYS)?
			.lock()
			.send_command(cmd.as_ref(), rsp.as_mut());
		trace!("unlink answer {:?}", rsp);

		Ok(())
	}

	fn rmdir(&self, path: &str) -> core::result::Result<(), FileError> {
		let (cmd, mut rsp) = Rmdir::build(path);
		get_filesystem_driver()
			.ok_or(FileError::ENOSYS)?
			.lock()
			.send_command(cmd.as_ref(), rsp.as_mut());
		trace!("rmdir answer {:?}", rsp);

		Ok(())
	}

	fn mkdir(&self, name: &str, mode: u32) -> Result<i32, FileError> {
		let (cmd, mut rsp) = Mkdir::build(name, mode);

		get_filesystem_driver()
			.ok_or(FileError::ENOSYS)?
			.lock()
			.send_command(cmd.as_ref(), rsp.as_mut());
		Ok(unsafe { rsp.body.assume_init().nodeid.try_into().unwrap() })
	}

	fn stat(&self, path: &str, stat: *mut FileAttr) -> Result<(), FileError> {
		debug!("FUSE stat: {}", path);

		// Is there a better way to implement this?
		let (cmd, mut rsp) = Lookup::build(path);
		get_filesystem_driver()
			.unwrap()
			.lock()
			.send_command(cmd.as_ref(), rsp.as_mut());

		if rsp.header.error != 0 {
			// TODO: Correct error handling
			return Err(FileError::EIO);
		}

		let rsp = unsafe { rsp.body.assume_init() };
		let attr = rsp.attr;

		if attr.mode & S_IFMT != S_IFLNK {
			unsafe {
				attr.fill_stat(stat);
			}
			Ok(())
		} else {
			self.stat(&self.readlink(rsp.nodeid)?, stat)
		}
	}

	fn lstat(&self, path: &str, stat: *mut FileAttr) -> Result<(), FileError> {
		let (cmd, mut rsp) = Lookup::build(path);
		get_filesystem_driver()
			.unwrap()
			.lock()
			.send_command(cmd.as_ref(), rsp.as_mut());

