fn poll(&self, events: PollEvent) -> PollEvent {
	let mut revents = PollEvent::empty();
	self.with(|socket| {
		match socket.state() {
			tcp::State::Closed | tcp::State::Closing | tcp::State::CloseWait => {
				revents |= PollEvent::POLLHUP;
			}
			tcp::State::FinWait1 | tcp::State::FinWait2 | tcp::State::TimeWait => {
				revents |= PollEvent::POLLHUP;
			}
			tcp::State::Listen => {}
			_ => {
				if self.listen.load(Ordering::Acquire) {
					if socket.is_active() {
						revents |= PollEvent::POLLIN;
					}
				} else {
					if socket.can_recv() {
						revents |= PollEvent::POLLIN;
					}
					if socket.can_send() {
						revents |= PollEvent::POLLOUT;
					}
				}
			}
		}
	});
	revents & events
}
```

