use core::future;
use core::task::{Poll, Waker};

use alloc::collections::VecDeque;
use hermit_sync::InterruptTicketMutex;

use crate::errno::*;
use crate::executor::block_on;
use crate::fd::{EventFlags, ObjectInterface, PollEvent};

/// State of an `EventFd`, protected by a mutex.
#[derive(Debug)]
struct EventState {
	counter: u64,
	read_queue: VecDeque<Waker>,
	write_queue: VecDeque<Waker>,
}

impl EventState {
	fn new(initval: u64) -> Self {
		Self {
			counter: initval,
			read_queue: VecDeque::new(),
			write_queue: VecDeque::new(),
		}
	}

	fn wake_readers(&mut self) {
		while let Some(waker) = self.read_queue.pop_front() {
			waker.wake();
		}
	}

	fn wake_writers(&mut self) {
		while let Some(waker) = self.write_queue.pop_front() {
			waker.wake();
		}
	}
}

/// An `eventfd` object, which provides a counter that can be used as an event
/// wait/notify mechanism.
pub struct EventFd {
	state: InterruptTicketMutex<EventState>,
	flags: EventFlags,
}

impl core::fmt::Debug for EventFd {
	fn fmt(&self, f: &mut core::fmt::Formatter<'_>) -> core::fmt::Result {
		let state = self.state.lock();
		f.debug_struct("EventFd")
			.field("counter", &state.counter)
			.field("flags", &self.flags)
			.finish()
	}
}

impl EventFd {
	pub fn new(initval: u64, flags: EventFlags) -> Self {
		Self {
			state: InterruptTicketMutex::new(EventState::new(initval)),
			flags,
		}
	}

	async fn async_read(&self, buf: &mut [u8]) -> Result<isize, i32> {
		future::poll_fn(|cx| {
			let mut state = self.state.lock();

			if state.counter > 0 {
				if self.flags.contains(EventFlags::EFD_SEMAPHORE) {
					state.counter -= 1;
					buf[..8].copy_from_slice(&1u64.to_ne_bytes());
				} else {
					let counter = state.counter;
					state.counter = 0;
					buf[..8].copy_from_slice(&counter.to_ne_bytes());
				}

				// wake up all writer task, since it is possible to write again
				state.wake_writers();

				Poll::Ready(Ok(8))
			} else {
				state.read_queue.push_back(cx.waker().clone());
				Poll::Pending
			}
		})
		.await
	}

	async fn async_write(&self, buf: &[u8]) -> Result<isize, i32> {
		let value = u64::from_ne_bytes(buf[..8].try_into().unwrap());

		future::poll_fn(|cx| {
			let mut state = self.state.lock();

			if let Some(new_counter) = state.counter.checked_add(value) {
				state.counter = new_counter;

				// wake up all reader task, since it is possible to read again
				state.wake_readers();

				Poll::Ready(Ok(8))
			} else {
				// the counter would overflow
				state.write_queue.push_back(cx.waker().clone());
				Poll::Pending
			}
		})
		.await
	}

	fn poll(&self, events: PollEvent) -> PollEvent {
		let state = self.state.lock();

		let mut revents = PollEvent::empty();
		if state.counter > 0 {
			revents |= PollEvent::POLLIN;
		}
		if state.counter < u64::MAX {
			revents |= PollEvent::POLLOUT;
		}

		revents & events
	}

	fn register(&self, waker: Waker) {
		let mut state = self.state.lock();
		state.read_queue.push_back(waker.clone());
		state.write_queue.push_back(waker);
	}
}

impl Clone for EventFd {
	fn clone(&self) -> Self {
		let state = EventState {
			counter: self.state.lock().counter,
			read_queue: VecDeque::new(),
			write_queue: VecDeque::new(),
		};

		Self {
			state: InterruptTicketMutex::new(state),
			flags: self.flags,
		}
	}
}

impl ObjectInterface for EventFd {
	fn read(&self, buf: *mut u8, len: usize) -> isize {
		if len < 8 {
			return (-EINVAL).try_into().unwrap();
		}

		let buf = unsafe { core::slice::from_raw_parts_mut(buf, len) };

		if self.flags.contains(EventFlags::EFD_NONBLOCK) {
			block_on(self.async_read(buf), Some(core::time::Duration::ZERO)).unwrap_or_else(|x| {
				if x == -ETIME {
					(-EAGAIN).try_into().unwrap()
				} else {
					x.try_into().unwrap()
				}
			})
		} else {
			block_on(self.async_read(buf), None).unwrap_or_else(|x| x.try_into().unwrap())
		}
	}

	fn write(&self, buf: *const u8, len: usize) -> isize {
		if len < 8 {
			return (-EINVAL).try_into().unwrap();
		}

		let buf = unsafe { core::slice::from_raw_parts(buf, len) };

		if self.flags.contains(EventFlags::EFD_NONBLOCK) {
			block_on(self.async_write(buf), Some(core::time::Duration::ZERO)).unwrap_or_else(
				|x| {
					if x == -ETIME {
						(-EAGAIN).try_into().unwrap()
					} else {
						x.try_into().unwrap()
					}
				},
			)
		} else {
			block_on(self.async_write(buf), None).unwrap_or_else(|x| x.try_into().unwrap())
		}
	}

	fn poll(&self, events: PollEvent) -> PollEvent {
		self.poll(events)
	}

	fn register(&self, waker: Waker) {
		self.register(waker)
	}
}

