/// Checks all file descriptors in `fds` for the requested events and returns
/// the number of file descriptors with available events.
///
/// If no file descriptor is ready yet, the future returns `Pending` after
/// registering a waker on each of them.
async fn poll_fds(fds: &mut [PollFd]) -> Result<u64, i32> {
	core::future::poll_fn(|cx| {
		let mut guard = OBJECT_MAP.read();

		let mut ready = 0;
		for i in fds {
			i.revents = PollEvent::empty();

			if i.fd < 0 {
				continue;
			}

			let Some(object) = guard.get(&i.fd) else {
				i.revents = PollEvent::POLLNVAL;
				ready += 1;
				continue;
			};

			let revents = object.poll(i.events);
			if revents.is_empty() {
				object.register(cx.waker());
			} else {
				i.revents = revents;
				ready += 1;
			}
		}

		if ready > 0 {
			core::task::Poll::Ready(Ok(ready))
		} else {
			core::task::Poll::Pending
		}
	})
	.await
}

/// Polls the given file descriptors for the requested events.
///
/// Blocks until at least one file descriptor is ready, or until the timeout is
/// reached. On timeout, `0` is returned.
pub(crate) fn poll(fds: &mut [PollFd], timeout: Option<Duration>) -> Result<u64, i32> {
	block_on(poll_fds(fds), timeout)
}

