use x86::io::inb;
use x86_64::instructions::port::Port;
use x86_64::structures::idt::InterruptStackFrame;

use super::apic;
use super::interrupts;

enum Inner {
	Uart {
		base: u16,
		serial: uart_16550::SerialPort,
	},
	Uhyve(Port<u8>),
}

pub struct SerialPort(Inner);

impl SerialPort {
	pub unsafe fn new(base: u16) -> Self {
		if crate::env::is_uhyve() {
			let serial = Port::new(base);
			Self(Inner::Uhyve(serial))
		} else {
			let mut serial = unsafe { uart_16550::SerialPort::new(base) };
			serial.init();
			Self(Inner::Uart { base, serial })
		}
	}

	pub fn send(&mut self, buf: &[u8]) {
		match &mut self.0 {
			Inner::Uhyve(s) => {
				for &data in buf {
					unsafe {
						s.write(data);
					}
				}
			}
			Inner::Uart { serial, .. } => {
				for &data in buf {
					serial.send(data);
				}
			}
		}
	}

	/// Receives a byte from the serial port, if one is available.
	pub fn receive(&mut self) -> Option<u8> {
		match &mut self.0 {
			Inner::Uhyve(_) => None,
			Inner::Uart { base, serial } => {
				// Check the Line Status Register for received data.
				if unsafe { inb(base + 5) } & 0x01 > 0 {
					Some(serial.receive())
				} else {
					None
				}
			}
		}
	}
}

/// Handler for interrupts of the first serial port (COM1).
///
/// Echoes all received non-control characters back to the serial port.
extern "x86-interrupt" fn serial_interrupt(_stack_frame: InterruptStackFrame) {
	let mut serial = super::COM1.lock();

	if let Some(serial) = serial.as_mut() {
		let mut buf = [0u8; 1];
		while let Some(character) = serial.receive() {
			// Ignore control characters.
			if character.is_ascii_graphic() || character == b' ' {
				buf[0] = character;
				serial.send(&buf);
			}
		}
	}

	apic::eoi();
}

/// Installs the interrupt handler for the first serial port (COM1).
pub fn install_serial_interrupt() {
	interrupts::irq_install_handler(4, serial_interrupt);
	interrupts::add_irq_name(4, "Serial IO");
}

