+/// Blocks the current task until the given future resolves or the timeout is reached.
+///
+/// While the future is pending, the executor is run and the task yields to the
+/// scheduler to allow other tasks to make progress.
+pub(crate) fn block_on<F, T>(future: F, timeout: Option<Duration>) -> Result<T, i32>
+where
+	F: Future<Output = Result<T, i32>>,
+{
+	let task_notify = Arc::new(TaskNotify::new());
+	let waker = task_notify.clone().into();
+	let mut cx = Context::from_waker(&waker);
+	let mut future = future;
+	let mut future = unsafe { core::pin::Pin::new_unchecked(&mut future) };
+
+	let start = crate::arch::kernel::systemtime::now_micros();
+
+	loop {
+		// run background tasks
+		run();
+
+		if let Poll::Ready(t) = future.as_mut().poll(&mut cx) {
+			return t;
+		}
+
+		// wait for a wakeup or until the timeout is reached
+		task_notify.wait(timeout.map(|t| t.as_micros() as u64));
+
+		if let Some(duration) = timeout {
+			if crate::arch::kernel::systemtime::now_micros() >= start + duration.as_micros() as u64
+			{
+				return Err(-crate::errno::ETIME);
+			}
+		}
+	}
+}
+
